'use strict';

var metadataHelpers = require('@toruslabs/metadata-helpers');
var mimcsponge = require('./mimcsponge.js');

function subkey(keyHex, input) {
  const privKeyBuf = metadataHelpers.hexToBigInt(metadataHelpers.add0x(keyHex)).toString(10);
  const curveN = metadataHelpers.secp256k1.Point.CURVE().n;
  const inputPath = metadataHelpers.mod(metadataHelpers.bytesToNumberBE(input), curveN).toString(10);
  const output = mimcsponge.mimcHash(1, privKeyBuf, inputPath);
  return output.xL.toString(16);
}

exports.subkey = subkey;
